// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";
import {SwarmRelay} from "src/SwarmRelay.sol";
import {OracleAsker} from "src/OracleAsker.sol";
import {MockIMD} from "src/MockIMD.sol";
import {APPROVED_OPERATOR, INTAKE, ORACLE_ACTION, ATTESTATION_RELAYER, ASK_TIMEOUT} from "src/DeploymentConfig.sol";

contract HourFeed2 is SwarmFeed {
    constructor(address attester_) SwarmFeed(attester_, ATTESTATION_RELAYER, 1, 3, 1 hours, 2_000) {}

    function seed(uint256 value) external {
        _accept(value, uint64(block.timestamp));
    }
}

contract ScratchIntake2 {
    struct Callback {
        address target;
        bytes4 selector;
    }

    mapping(bytes32 => mapping(address => uint256)) public priceOf;
    mapping(bytes32 => Callback) public callbackOf;
    uint256 public nonce;
    bytes public lastRevert;

    function setPrice(bytes32 action, address asset, uint256 amount) external {
        priceOf[action][asset] = amount;
    }

    function request(bytes32 action, bytes calldata, Callback calldata callback, address asset, uint256 amount)
        external
        payable
        returns (bytes32 requestId)
    {
        require(priceOf[action][asset] != 0 && amount >= priceOf[action][asset], "not sold");
        IERC20(asset).transferFrom(msg.sender, address(this), amount);
        requestId = keccak256(abi.encode(address(this), ++nonce));
        callbackOf[requestId] = callback;
    }

    function complete(bytes32 requestId, bytes calldata args) external returns (bool delivered) {
        Callback memory c = callbackOf[requestId];
        bytes memory ret;
        (delivered, ret) = c.target.call{gas: 200_000}(bytes.concat(c.selector, args));
        lastRevert = ret;
    }
}

/// @notice FINDING (low). `OracleAsker._request` deletes `feedOf[f.inFlight]` when a new request replaces
/// one that has passed ASK_TIMEOUT, so when the Intake later delivers the OLD request — paid for by the
/// Treasury or by an askPaid caller — `onOracleResult` reverts `UnknownRequest` and the answer is never
/// relayed. The function's own contract is "never revert past this point ... An answer it could not
/// deliver stays public, and anyone can relay it by hand"; here it reverts before that point, and the
/// Intake records a failed callback for a request someone paid 0.5 IMD for. The `f.inFlight == requestId`
/// check already handles a late delivery safely, so the delete buys nothing.
///
/// Fails on the committed code (the late callback reverts); passes once `_request` stops deleting the
/// superseded request's `feedOf` entry.
contract LateDeliveryDroppedTest is Test {
    uint256 private constant ATTESTER_KEY = 0xA11CE;
    uint256 private constant PRICE = 0.5 ether;
    uint256 private constant V = 3_550_000 gwei;
    bytes private constant BODY = '{"question":"IMD/ETH median"}';
    address private constant PAYER = address(0xFACE);

    MockIMD private imd;
    ScratchIntake2 private intake;
    HourFeed2 private feed;
    OracleAsker private asker;

    function setUp() public {
        vm.chainId(1);
        vm.warp(100 days);
        vm.roll(1_000_000);
        vm.etch(ATTESTATION_RELAYER, address(new SwarmRelay()).code);
        vm.etch(INTAKE, address(new ScratchIntake2()).code);
        intake = ScratchIntake2(INTAKE);
        imd = new MockIMD();
        intake.setPrice(ORACLE_ACTION, address(imd), PRICE);
        feed = new HourFeed2(vm.addr(ATTESTER_KEY));
        address[] memory feeds = new address[](1);
        feeds[0] = address(feed);
        bytes32[] memory hashes = new bytes32[](1);
        hashes[0] = keccak256(BODY);
        bool[] memory tracks = new bool[](1);
        tracks[0] = true;
        bool[] memory keepAlive = new bool[](1);
        asker = new OracleAsker(IERC20(address(imd)), feeds, hashes, tracks, keepAlive);
        vm.prank(APPROVED_OPERATOR);
        imd.mint(PAYER, 10 ether);
        feed.seed(V);
    }

    function test_aLateAnswerToASupersededRequestIsStillRelayed() public {
        vm.startPrank(PAYER);
        imd.approve(address(asker), type(uint256).max);
        bytes32 first = asker.askPaid(address(feed), BODY, PRICE);
        // The panel is slow: nothing is delivered for ASK_TIMEOUT, so the same payer (or anyone) asks again.
        vm.warp(block.timestamp + ASK_TIMEOUT);
        vm.roll(block.number + ASK_TIMEOUT / 12);
        bytes32 second = asker.askPaid(address(feed), BODY, PRICE);
        vm.stopPrank();
        assertTrue(first != second);
        assertEq(asker.feedOf(first), address(0), "the superseded request was forgotten");

        // The Intake now delivers the FIRST answer, signed a moment ago (a valid, fresh attestation).
        SwarmFeed.OracleAttestation memory a = _attestation(keccak256("late"), V * 101 / 100);
        bool delivered = intake.complete(first, abi.encode(first, a, _sign(a)));

        // EXPECTED: the callback completes (it promises never to revert once the request is known to be
        // this asker's) and the paid-for answer lands in the feed.
        assertEq(bytes4(intake.lastRevert()), bytes4(0), "callback reverted (UnknownRequest)");
        assertTrue(delivered, "the Intake recorded a failed callback for a paid request");
        (uint256 value,) = feed.latestValue();
        assertEq(value, V * 101 / 100, "the answer PAYER paid 0.5 IMD for never landed");
    }

    function _attestation(bytes32 id, uint256 figure) private view returns (SwarmFeed.OracleAttestation memory a) {
        a.requestId = id;
        a.chainId = 1;
        a.questionHash = keccak256("q");
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.fromBlock = uint64(block.number - 600);
        a.toBlock = uint64(block.number);
        a.blockHash = keccak256("b");
        a.panelJobId = keccak256("panel");
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 40;
        a.issuedAt = uint64(block.timestamp);
        a.expiresAt = uint64(block.timestamp + 1 days);
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    feed.ATTESTATION_TYPEHASH(),
                    a.requestId,
                    a.chainId,
                    a.questionHash,
                    a.answerType,
                    keccak256(a.answer),
                    a.figure,
                    a.fromBlock
                ),
                abi.encode(
                    a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed, a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(ATTESTER_KEY, keccak256(abi.encodePacked("\x19\x01", feed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}
